def get_blocks(g):
    h,w=len(g),len(g[0])
    for i in range(h):
        if len(set(g[i]))==1:
            A=[r[:w] for r in g[:i]]; B=[r[:w] for r in g[i+1:]]
            if A and B and len(A)==len(B): return A,B,g[i][0],'row'
    for j in range(w):
        if len(set(g[i][j] for i in range(h)))==1:
            A=[r[:j] for r in g]; B=[r[j+1:] for r in g]
            if A and B and len(A[0])==len(B[0]): return A,B,g[0][j],'col'

for i,p in enumerate(d):
